#include <iostream>
#include <string>
using namespace std;

int main() {
    int c;
    cin >> c;
    int* st = new int[c];
    int* top = st;
    int total = c;
    while (total > 0) {
        total--;
        string cmd;
        cin >> cmd;
        if (cmd == "push") {
            int x;
            cin >> x;
            *top = x;
            top++;
        } else if (cmd == "pop") {
            if (top == st) {
                cout << "UNDERFLOW" << endl;
            } else {
                top--;
                cout << *top << endl;
            }
        } else if (cmd == "peek") {
            if (top == st) {
                cout << "UNDERFLOW" << endl;
            } else {
                cout << *(top - 1) << endl;
            }
        }
    }
    cout << "Stack from top: ";
    int remaining = top - st;
    if (remaining == 0) {
        cout << "EMPTY";
    } else {
        for (int i = remaining - 1; i >= 0; i--) {
            cout << *(st + i);
            if (i > 0) {
                cout << " ";
            }
        }
    }
    cout << endl;
    delete[] st;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int r, c;
    cin >> r >> c;
    int ri, rj;
    cin >> ri >> rj;
    int* mat = new int[r * c];
    int* p = mat;
    for (int i = 0; i < r * c; i++) {
        cin >> *p;
        p++;
    }
    int* rowA = mat + ri * c;
    int* rowB = mat + rj * c;
    for (int k = 0; k < c; k++) {
        int temp = *(rowA + k);
        *(rowA + k) = *(rowB + k);
        *(rowB + k) = temp;
    }
    for (int i = 0; i < r; i++) {
        for (int k = 0; k < c; k++) {
            cout << *(mat + i * c + k);
            if (k < c - 1) {
                cout << " ";
            }
        }
        cout << endl;
    }
    delete[] mat;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int n, w;
    cin >> n >> w;
    int arr[1000];
    int* p = arr;
    for (int i = 0; i < n; i++) {
        cin >> *p;
        p++;
    }
    int sum = 0;
    for (int i = 0; i < w; i++) {
        sum += *(arr + i);
    }
    int best = sum;
    cout << "Window sums: " << sum;
    int* add = arr + w;
    int* drop = arr;
    for (int i = w; i < n; i++) {
        sum += *add - *drop;
        add++;
        drop++;
        if (sum > best) {
            best = sum;
        }
        cout << " " << sum;
    }
    cout << endl;
    cout << "Max window sum: " << best << endl;
    return 0;
}

